-- 0035_fold_repo_path_case.sql — fold the repository PATH case onto ONE
-- canonical form for every persisted and derived identity.
--
-- Repository path case used to be identity-bearing: repo_url
-- https://github.com/Acme/Backend.git stored the canonical ID
-- github.com/Acme/Backend, which did NOT equal an explicit
-- github.com/acme/backend deny and matched none of that repository's policies
-- (fail open). The Go identity now folds the path (auth.FoldRepoFullName) and
-- kiwi_canonical_repo_id / kiwi_normalize_run_repo_identity /
-- kiwi_normalize_run_repo_full_name fold it identically in SQL (ASCII LOWER of
-- the full-name portion, host preserved, r1:/a1: spellings untouched).
--
-- Migrations 0027/0034 already carry the folded bodies for a fresh database,
-- this migration converges an ALREADY-MIGRATED database:
--   * replace the three IMMUTABLE functions (a shipped migration cannot be
--     re-run, and CREATE OR REPLACE is the only upgrade path)
--   * re-stamp every runs row whose materialized normalized columns were
--     computed with the unfolded derivation
--   * rebuild runs_repo_identity_idx and the two normalized keyset indexes,
--     whose entries were computed by the replaced function bodies and would
--     otherwise be stale.
--
-- DEPLOY-SAFETY: the function replacements and the row re-stamp are
-- correctness-only. The index rebuilds are non-concurrent like the other
-- index migrations (CREATE INDEX CONCURRENTLY cannot run inside the runner's
-- transaction).

CREATE OR REPLACE FUNCTION kiwi_canonical_repo_id(payload jsonb, url_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$SELECT CASE WHEN LEFT(COALESCE(NULLIF(BTRIM(payload->>'repo_id'), ''), CASE WHEN CASE WHEN BTRIM(COALESCE(payload->>'repo_full_name', '')) <> '' THEN BTRIM(COALESCE(payload->>'repo_full_name', '')) ELSE BTRIM(REGEXP_REPLACE(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN COALESCE(SUBSTRING(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3) FROM '/(.*)$'), '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), ':') + 1) ELSE COALESCE(payload->>url_key, '') END, '\.git$', ''), '/') END = '' THEN '' WHEN CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN REGEXP_REPLACE(SPLIT_PART(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3), '/', 1), '^.*@', '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), ':', 1), '^.*@', '') ELSE REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), '/', 1), '^.*@', '') END = '' OR LEFT(CASE WHEN BTRIM(COALESCE(payload->>'repo_full_name', '')) <> '' THEN BTRIM(COALESCE(payload->>'repo_full_name', '')) ELSE BTRIM(REGEXP_REPLACE(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN COALESCE(SUBSTRING(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3) FROM '/(.*)$'), '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), ':') + 1) ELSE COALESCE(payload->>url_key, '') END, '\.git$', ''), '/') END, LENGTH(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN REGEXP_REPLACE(SPLIT_PART(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3), '/', 1), '^.*@', '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), ':', 1), '^.*@', '') ELSE REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), '/', 1), '^.*@', '') END) + 1) = CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN REGEXP_REPLACE(SPLIT_PART(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3), '/', 1), '^.*@', '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), ':', 1), '^.*@', '') ELSE REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), '/', 1), '^.*@', '') END || '/' THEN CASE WHEN BTRIM(COALESCE(payload->>'repo_full_name', '')) <> '' THEN BTRIM(COALESCE(payload->>'repo_full_name', '')) ELSE BTRIM(REGEXP_REPLACE(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN COALESCE(SUBSTRING(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3) FROM '/(.*)$'), '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), ':') + 1) ELSE COALESCE(payload->>url_key, '') END, '\.git$', ''), '/') END ELSE CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN REGEXP_REPLACE(SPLIT_PART(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3), '/', 1), '^.*@', '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), ':', 1), '^.*@', '') ELSE REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), '/', 1), '^.*@', '') END || '/' || CASE WHEN BTRIM(COALESCE(payload->>'repo_full_name', '')) <> '' THEN BTRIM(COALESCE(payload->>'repo_full_name', '')) ELSE BTRIM(REGEXP_REPLACE(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN COALESCE(SUBSTRING(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3) FROM '/(.*)$'), '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), ':') + 1) ELSE COALESCE(payload->>url_key, '') END, '\.git$', ''), '/') END END), 3) IN ('r1:', 'a1:') THEN COALESCE(NULLIF(BTRIM(payload->>'repo_id'), ''), CASE WHEN CASE WHEN BTRIM(COALESCE(payload->>'repo_full_name', '')) <> '' THEN BTRIM(COALESCE(payload->>'repo_full_name', '')) ELSE BTRIM(REGEXP_REPLACE(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN COALESCE(SUBSTRING(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3) FROM '/(.*)$'), '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), ':') + 1) ELSE COALESCE(payload->>url_key, '') END, '\.git$', ''), '/') END = '' THEN '' WHEN CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN REGEXP_REPLACE(SPLIT_PART(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3), '/', 1), '^.*@', '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), ':', 1), '^.*@', '') ELSE REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), '/', 1), '^.*@', '') END = '' OR LEFT(CASE WHEN BTRIM(COALESCE(payload->>'repo_full_name', '')) <> '' THEN BTRIM(COALESCE(payload->>'repo_full_name', '')) ELSE BTRIM(REGEXP_REPLACE(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN COALESCE(SUBSTRING(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3) FROM '/(.*)$'), '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), ':') + 1) ELSE COALESCE(payload->>url_key, '') END, '\.git$', ''), '/') END, LENGTH(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN REGEXP_REPLACE(SPLIT_PART(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3), '/', 1), '^.*@', '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), ':', 1), '^.*@', '') ELSE REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), '/', 1), '^.*@', '') END) + 1) = CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN REGEXP_REPLACE(SPLIT_PART(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3), '/', 1), '^.*@', '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), ':', 1), '^.*@', '') ELSE REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), '/', 1), '^.*@', '') END || '/' THEN CASE WHEN BTRIM(COALESCE(payload->>'repo_full_name', '')) <> '' THEN BTRIM(COALESCE(payload->>'repo_full_name', '')) ELSE BTRIM(REGEXP_REPLACE(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN COALESCE(SUBSTRING(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3) FROM '/(.*)$'), '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), ':') + 1) ELSE COALESCE(payload->>url_key, '') END, '\.git$', ''), '/') END ELSE CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN REGEXP_REPLACE(SPLIT_PART(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3), '/', 1), '^.*@', '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), ':', 1), '^.*@', '') ELSE REGEXP_REPLACE(SPLIT_PART(COALESCE(payload->>url_key, ''), '/', 1), '^.*@', '') END || '/' || CASE WHEN BTRIM(COALESCE(payload->>'repo_full_name', '')) <> '' THEN BTRIM(COALESCE(payload->>'repo_full_name', '')) ELSE BTRIM(REGEXP_REPLACE(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN COALESCE(SUBSTRING(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3) FROM '/(.*)$'), '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), ':') + 1) ELSE COALESCE(payload->>url_key, '') END, '\.git$', ''), '/') END END) WHEN STRPOS(COALESCE(NULLIF(BTRIM(payload->>'repo_id'), ''), CASE WHEN CASE WHEN BTRIM(COALESCE(payload->>'repo_full_name', '')) <> '' THEN BTRIM(COALESCE(payload->>'repo_full_name', '')) ELSE BTRIM(REGEXP_REPLACE(CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN COALESCE(SUBSTRING(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3) FROM '/(.*)$'), '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(COALESCE(payload->>url_key, ''), ':')) THEN SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), ':') + 1) ELSE COALESCE(payload->>url_key, '') END, '\.git$', ''), '/') END = '' THEN '' WHEN CASE WHEN STRPOS(COALESCE(payload->>url_key, ''), '://') > 0 THEN REGEXP_REPLACE(SPLIT_PART(SUBSTRING(COALESCE(payload->>url_key, '') FROM STRPOS(COALESCE(payload->>url_key, ''), '://') + 3), '/', 1), '^.*@', '') WHEN STRPOS(COALESCE(payload->>url_key, ''), ':') > 0 AND (STRPOS(COALESCE(payload->>url_key, ''), '/') = 0 OR STRPOS(COALESCE(payload->>url_key, ''), '/') > STRPOS(