CREATE OR REPLACE FUNCTION kiwi_normalize_run_repo_identity(payload jsonb, url_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$SELECT CASE WHEN (STRPOS(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), '/') > 0 AND STRPOS(SUBSTRING(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)) FROM STRPOS(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), '/') + 1), '/') > 0) THEN CASE WHEN kiwi_canonical_host(CASE WHEN STRPOS(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), '/') > 0 THEN LEFT(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), STRPOS(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), '/') - 1) ELSE '' END) = '' THEN COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)) ELSE kiwi_canonical_host(CASE WHEN STRPOS(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), '/') > 0 THEN LEFT(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), STRPOS(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), '/') - 1) ELSE '' END) || '/' || LOWER(SUBSTRING(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)) FROM STRPOS(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), '/') + 1)) END ELSE '' END$$;

CREATE OR REPLACE FUNCTION kiwi_normalize_run_repo_full_name(payload jsonb, url_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$SELECT CASE WHEN (STRPOS(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), '/') > 0 AND STRPOS(SUBSTRING(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)) FROM STRPOS(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), '/') + 1), '/') > 0) THEN LOWER(SUBSTRING(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)) FROM STRPOS(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), '/') + 1)) ELSE CASE WHEN LEFT(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)), 3) IN ('r1:', 'a1:') THEN COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key)) ELSE LOWER(COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, url_key))) END END$$;

UPDATE runs SET repo_identity_normalized = kiwi_normalize_run_repo_identity(payload, 'repo'), repo_full_name_normalized = kiwi_normalize_run_repo_full_name(payload, 'repo') WHERE repo_identity_normalized IS DISTINCT FROM kiwi_normalize_run_repo_identity(payload, 'repo') OR repo_full_name_normalized IS DISTINCT FROM kiwi_normalize_run_repo_full_name(payload, 'repo');

DROP INDEX IF EXISTS runs_repo_identity_idx;

CREATE INDEX IF NOT EXISTS runs_repo_identity_idx
    ON runs ((COALESCE(NULLIF(BTRIM(payload->>'policy_repo_id'), ''), kiwi_canonical_repo_id(payload, 'repo'))));

DROP INDEX IF EXISTS runs_repo_identity_normalized_keyset_idx;

CREATE INDEX IF NOT EXISTS runs_repo_identity_normalized_keyset_idx
    ON runs (repo_identity_normalized, created_at DESC, id COLLATE "C" DESC);

DROP INDEX IF EXISTS runs_repo_full_name_normalized_keyset_idx;

CREATE INDEX IF NOT EXISTS runs_repo_full_name_normalized_keyset_idx
    ON runs (repo_full_name_normalized, created_at DESC, id COLLATE "C" DESC);
